'use strict';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let language=new URLSearchParams(location.search).get('lang');
if(!['id','en'].includes(language)){try{language=localStorage.getItem('cs-report-grade8-language')||'en';}catch{language='en';}}
if(!['id','en'].includes(language))language='en';
const t=(id,en)=>language==='id'?id:en;
const tx=pair=>Array.isArray(pair)?pair[language==='id'?0:1]:pair;
let storageKey=null,practice={lessons:{}},storageAvailable=true,currentLesson=null,toastTimer;
function teacherMode(){return g8TeacherVerified===true&&g8Session?.isTeacherPreview===true;}
function lessonRecord(id){if(!practice.lessons[id])practice.lessons[id]={done:false,evidence:'',reflection:'',quiz:{draft:[],best:null,last:null}};return practice.lessons[id];}
function restorePractice(){storageKey='cs-report-grade8-games-v1:'+encodeURIComponent(g8Session.id);try{const raw=JSON.parse(localStorage.getItem(storageKey)||'null');if(raw?.lessons&&typeof raw.lessons==='object')for(const l of LESSONS){const r=raw.lessons[l.id];if(r&&typeof r==='object'){const q=r.quiz||{};practice.lessons[l.id]={done:r.done===true,evidence:typeof r.evidence==='string'?r.evidence:'',reflection:typeof r.reflection==='string'?r.reflection:'',quiz:{draft:Array.isArray(q.draft)?q.draft.map(v=>Number.isInteger(v)&&v>=0&&v<3?v:null):[],best:Number.isFinite(q.best)?Math.max(0,Math.min(100,q.best)):null,last:Number.isFinite(q.last)?Math.max(0,Math.min(100,q.last)):null}};}}}catch{storageAvailable=false;}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(practice));return true;}catch{storageAvailable=false;toast(t('Belum tersimpan. Unduh catatan sebelum menutup halaman.','Could not save. Download your notes before closing.'));return false;}}
function sourceByName(name){return BSD_SOURCES.find(s=>s.name===name);}
function localizeShell(){document.documentElement.lang=language;$('language').value=language;const labels={'gate-title':t('Buka Game Studio dari halaman nilaimu.','Open Game Studio from your grade page.'),'gate-copy':t('Cari nama atau NIS di CS.Report, masukkan password siswa, lalu pilih Buka Game Studio.','Search for your name or student ID in CS.Report, enter your student password, then choose Open Game Studio.'),'gate-link':t('Cari nama di CS.Report →','Find your name in CS.Report →'),'skip':t('Langsung ke materi','Skip to content'),'nav-home':t('Pertemuan','Lessons'),'nav-project':t('Game final','Final game'),'nav-teacher':t('Panduan guru','Teacher guide'),'book-link':t('Buku nilai ↗','Gradebook ↗'),'footer-copy':t('BSD Mobile Game Developer · 8 pertemuan × 2 JP','BSD Mobile Game Developer · 8 meetings × 2 periods'),'storage-copy':t('Catatan latihan tersimpan pada browser ini. Nilai resmi dicatat di CS.Report.','Practice notes are saved on this browser. Official grades are recorded in CS.Report.')};for(const[id,text]of Object.entries(labels))$(id).textContent=text;}
function homeHTML(){const done=LESSONS.filter(l=>lessonRecord(l.id).done).length,next=LESSONS.find(l=>!lessonRecord(l.id).done)?.id||1;return '<section class="home-intro"><p class="eyebrow">BSD · MOBILE GAME DEVELOPER</p><h1>'+t('Mainkan. Ubah. Jelaskan.','Play. Modify. Explain.')+'</h1><p>'+t('Tujuan utama: membuat dan memodifikasi game HTML, CSS, dan JavaScript; menguji hasilnya dan menjelaskan perubahanmu.','Main goal: build and customize HTML, CSS, and JavaScript games; test the result and explain your changes.')+'</p><p>'+t('8 pertemuan · 80 menit. Buka tugas → praktik di BSD → coba tantangan.','8 meetings · 80 minutes each. Open the task → practise in BSD → try the challenge.')+'</p><div class="actions"><a class="btn" href="#lesson/'+next+'">'+t('Lanjutkan belajar →','Continue learning →')+'</a><a class="btn secondary" href="#project">'+t('Lihat game final','View the final game')+'</a></div><p class="small" style="margin-top:12px">'+done+'/8 '+t('pertemuan ditandai selesai.','meetings marked complete.')+'</p></section><h2>'+t('Pilih pertemuan','Choose a meeting')+'</h2><div class="lesson-list">'+LESSONS.map(l=>'<a class="lesson-link" href="#lesson/'+l.id+'"><span class="lesson-number">'+String(l.id).padStart(2,'0')+'</span><div><b>'+esc(tx(l.title))+'</b><small>'+esc(tx(l.result))+'</small></div><strong>'+(lessonRecord(l.id).done?'✓':'→')+'</strong></a>').join('')+'</div><p class="small">'+t('Game 3–6 memakai checkpoint dari guru. Pengerjaan course lengkap dapat dilanjutkan di BSD sesuai arahan guru.','Games in meetings 3–6 use teacher checkpoints. Continue the full course in BSD as directed by your teacher.')+'</p>';}
function lessonHTML(l){const r=lessonRecord(l.id),primary=sourceByName(l.sources[0]);return '<div class="breadcrumbs"><a href="#home">'+t('Pertemuan','Meetings')+'</a> / '+l.id+'</div><header class="lesson-heading"><p class="eyebrow">'+t('PERTEMUAN ','MEETING ')+l.id+' · 80 '+t('MENIT','MINUTES')+'</p><h1>'+esc(tx(l.title))+'</h1><p>'+esc(tx(l.goal))+'</p></header><div class="classroom"><section class="panel task-card"><p class="eyebrow">01 · '+t('KERJAKAN','GET STARTED')+'</p><h2>'+t('Tugas hari ini','Today’s task')+'</h2><p class="bsd-route"><b>BSD:</b> '+l.sources.map(n=>esc(sourceByName(n).title)).join(' · ')+'<br>'+esc(l.range)+'</p>'+(l.starter?'<p class="starter">'+esc(tx(l.starter))+'</p>':'')+'<ol class="task-steps">'+l.tasks.map(s=>'<li>'+esc(tx(s))+'</li>').join('')+'</ol><a class="btn" href="'+esc(primary.url)+'" target="_blank" rel="noopener noreferrer">'+t('Buka proyek BSD ↗','Open BSD project ↗')+'</a></section><section class="panel challenge-card"><p class="eyebrow">02 · '+t('COBA SENDIRI','TRY IT YOURSELF')+'</p><h2>'+t('Tantangan','Challenge')+'</h2><p>'+esc(tx(l.challenge))+'</p><p class="small">'+esc(tx(l.check))+'</p><div class="result-target"><b>'+t('Tunjukkan hasil: ','Show your result: ')+'</b>'+esc(tx(l.result))+'</div></section><section class="panel result-card"><h2>'+t('Simpan hasilmu','Save your result')+'</h2><label for="evidence">'+t('Tautan karya / catatan perubahan','Project link / change note')+'</label><textarea rows="2" id="evidence" placeholder="'+t('Tautan atau satu kalimat tentang hasilmu…','A link or one sentence about your result…')+'">'+esc(r.evidence)+'</textarea><label for="reflection">'+t('Apa yang berubah setelah kamu coba?','What changed after you tried it?')+'</label><textarea rows="2" id="reflection" placeholder="'+t('Satu kalimat cukup.','One sentence is enough.')+'">'+esc(r.reflection)+'</textarea><p class="small">'+(storageAvailable?t('Tersimpan otomatis pada browser ini. Tunjukkan karya kepada guru.','Saved automatically on this browser. Show your work to your teacher.'):t('Unduh catatan untuk menyimpan hasil.','Download your notes to keep your work.'))+'</p><div class="actions"><button id="complete" class="btn '+(r.done?'done':'')+'">'+(r.done?t('✓ Ditandai selesai','✓ Marked complete'):t('Tandai latihan selesai','Mark practice complete'))+'</button><button id="download-note" class="btn secondary">'+t('Unduh catatan','Download notes')+'</button></div></section><details class="panel optional"><summary>'+t('Ringkasan & kuis latihan (pilihan)','Summary & practice quiz (optional)')+'</summary><div><p class="concept-summary">'+esc(tx(l.learn))+'</p><p class="small">'+t('3 soal pendamping · dapat diulang · bukan nilai resmi BSD.','3 companion questions · retry any time · separate from official BSD grades.')+'</p><div id="practice-quiz">'+quizHTML(l)+'</div></div></details>'+(teacherMode()?'<details class="panel teacher-details"><summary>'+t('Pengantar & catatan guru','Teacher introduction & notes')+'</summary>'+teacherLessonHTML(l)+'</details>':'')+'<div class="actions lesson-next">'+(l.id>1?'<a class="btn secondary" href="#lesson/'+(l.id-1)+'">← '+t('Sebelumnya','Previous')+'</a>':'')+(l.id<8?'<a class="btn secondary" href="#lesson/'+(l.id+1)+'">'+t('Pertemuan ','Meeting ')+(l.id+1)+' →</a>':'<a class="btn secondary" href="#project">'+t('Game final →','Final game →')+'</a>')+'</div></div>';}
function quizHTML(l){const q=lessonRecord(l.id).quiz,finished=q.last!==null;return (finished?'<div class="quiz-result" role="status"><b>'+q.last+'/100</b> · '+t('terbaik: ','best: ')+q.best+'/100</div>':'')+'<form id="quiz-form" class="quiz">'+l.questions.map((question,i)=>'<fieldset><legend>'+(i+1)+'. '+esc(tx(question.stem))+'</legend>'+question.options.map((option,j)=>'<label><input type="radio" name="q'+i+'" value="'+j+'" '+(q.draft[i]===j?'checked':'')+' '+(finished?'disabled':'')+' required><span>'+esc(tx(option))+'</span></label>').join('')+(finished?'<p class="explanation">'+(q.draft[i]===question.key?'✓ ':'↗ ')+t('Jawaban: ','Answer: ')+esc(tx(question.options[question.key]))+'. '+esc(tx(question.why))+'</p>':'')+'</fieldset>').join('')+'<button class="btn" type="submit" '+(finished?'disabled':'')+'>'+t('Periksa jawaban','Check answers')+'</button></form>'+(finished?'<button class="btn secondary" id="retry" style="margin-top:12px">'+t('Ulangi latihan','Retry practice')+'</button>':'');}
function recordQuiz(l,answers){if(answers.length!==l.questions.length||answers.some(a=>!Number.isInteger(a)||a<0||a>2))return false;const q=lessonRecord(l.id).quiz,score=Math.round(answers.filter((a,i)=>a===l.questions[i].key).length/answers.length*100);q.draft=answers.slice();q.last=score;q.best=q.best===null?score:Math.max(q.best,score);save();return true;}
function bindQuiz(l){const form=$('quiz-form');form.addEventListener('change',()=>{const q=lessonRecord(l.id).quiz;q.draft=l.questions.map((_,i)=>{const el=form.querySelector('input[name="q'+i+'"]:checked');return el?Number(el.value):null;});save();});form.addEventListener('submit',event=>{event.preventDefault();const answers=l.questions.map((_,i)=>{const el=form.querySelector('input[name="q'+i+'"]:checked');return el?Number(el.value):null;});if(!recordQuiz(l,answers))return;$('practice-quiz').innerHTML=quizHTML(l);bindQuiz(l);});if($('retry'))$('retry').addEventListener('click',()=>{const q=lessonRecord(l.id).quiz;q.last=null;q.draft=[];save();$('practice-quiz').innerHTML=quizHTML(l);bindQuiz(l);});}
function bindLesson(l){for(const key of ['evidence','reflection'])$(key).addEventListener('input',()=>{lessonRecord(l.id)[key]=$(key).value;save();});$('complete').addEventListener('click',()=>{const r=lessonRecord(l.id);r.done=!r.done;save();$('complete').classList.toggle('done',r.done);$('complete').textContent=r.done?t('✓ Ditandai selesai','✓ Marked complete'):t('Tandai latihan selesai','Mark practice complete');toast(t('Catatan latihan diperbarui.','Practice record updated.'));});$('download-note').addEventListener('click',()=>download('game-studio-meeting-'+l.id+'.txt',noteText(l)));bindQuiz(l);}
function noteText(l){const r=lessonRecord(l.id);return l.id+'. '+tx(l.title)+'\n\n'+t('Hasil: ','Result: ')+r.evidence+'\n'+t('Refleksi: ','Reflection: ')+r.reflection+'\n'+t('Selesai: ','Complete: ')+r.done+'\n'+t('Skor latihan terbaik: ','Best practice score: ')+(r.quiz.best??'—')+'\n\n'+t('Catatan pribadi pada browser ini; bukan nilai resmi.','Personal browser notes; separate from official grades.');}
function download(name,text){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function teacherLessonHTML(l){if(!teacherMode())return '';return '<p><b>'+t('Pengantar lisan: ','Spoken introduction: ')+'</b>'+esc(tx(l.goal))+' '+esc(tx(l.learn))+' '+t('Hari ini buka ','Today open ')+esc(l.range)+'. '+t('Hasil yang saya harapkan: ','Expected result: ')+esc(tx(l.result))+'</p><p><b>'+t('Persiapan & batas: ','Preparation & scope: ')+'</b>'+esc(tx(l.prep))+'</p><p><b>'+t('Saat berkeliling: ','While circulating: ')+'</b>'+esc(tx(l.oral))+'</p><p><b>WKA / BCW: </b>'+esc(tx(l.wka))+'</p><h3>'+t('Agenda 80 menit','80-minute agenda')+'</h3><ul>'+l.times.map(([s,n])=>'<li>'+esc(tx(s.split('|')))+' · '+n+' '+t('menit','minutes')+'</li>').join('')+'</ul>';}
function teacherHTML(){if(!teacherMode())return homeHTML();return '<p class="eyebrow">'+t('KELAS 8 · PANDUAN GURU','GRADE 8 · TEACHER GUIDE')+'</p><h1>'+t('Pimpin praktik. Periksa pemahaman.','Lead practice. Check understanding.')+'</h1><div class="teacher-grid"><section class="panel"><h2>'+t('Cakupan 8 pertemuan','Scope of eight meetings')+'</h2><p>'+t('Overview BSD: lima game × sekitar 5 jam = 25 jam. Alokasi kelas: 8 × 80 menit = 10 jam 40 menit. Rencana ini mencakup konsep inti dan modifikasi lima game dengan checkpoint guru; bukan pengerjaan seluruh guided project dari nol.','BSD overview: five games × about five hours = 25 hours. Class allocation: 8 × 80 minutes = 10 hours 40 minutes. This plan covers core concepts and modifications across five games using teacher checkpoints; it does not rebuild every guided project from scratch.')+'</p><p>'+t('Prasyarat: siswa pernah memakai HTML, CSS, dan JavaScript. Siapkan salinan Sandbox berjalan untuk Traffic, Nonogram, Dungeon, dan Wall Jumper. Tandai kode sasaran sebelum kelas; sediakan link salinan melalui kanal kelas. Bila wajib menuntaskan seluruh course BSD, jadwalkan pekerjaan mandiri atau tambah waktu.','Prerequisite: previous HTML, CSS, and JavaScript experience. Prepare working Sandbox copies for Traffic, Nonogram, Dungeon, and Wall Jumper. Mark target code before class; share copy links through the class channel. If full BSD course completion is required, assign independent work or add time.')+'</p><p>'+t('Tanpa diagnostik wajib. Pembuka cukup demo dan satu pertanyaan lisan. Formatif: hasil kode, tantangan, dan alasan perubahan. Sumatif: game pilihan, demo individual, modifikasi, serta cek konsep untuk materi yang diajarkan.','No mandatory diagnostic. Open with a demo and one spoken question. Formative evidence: code results, challenges, and reasons for changes. Summative evidence: a chosen game, individual demo, modification, and a concept check for taught material.')+'</p><div class="actions"><button id="download-guide" class="btn">'+t('Unduh 8 panduan & kunci latihan','Download eight guides & practice keys')+'</button><a class="btn secondary" href="#project">'+t('Kriteria karya final','Final work criteria')+'</a></div></section><section class="panel"><h2>'+t('Peta materi','Learning map')+'</h2><div class="table-scroll"><table class="teacher-map"><thead><tr><th>#</th><th>BSD</th><th>'+t('Fokus & hasil','Focus & result')+'</th></tr></thead><tbody>'+LESSONS.map(l=>'<tr><td><a href="#lesson/'+l.id+'">'+l.id+'</a></td><td>'+esc(l.range)+'</td><td>'+esc(tx(l.result))+'</td></tr>').join('')+'</tbody></table></div></section>'+LESSONS.map(l=>'<details class="panel teacher-details"><summary>'+l.id+'. '+esc(tx(l.title))+'</summary>'+teacherLessonHTML(l)+'</details>').join('')+'<details class="panel teacher-details"><summary>'+t('Sumber & batas pemeriksaan','Sources & review scope')+'</summary><p>'+t('Classroom “8 test” diperiksa di Chrome. Definisi enam proyek (120 langkah) serta sembilan PDF overview, progression, introduction, dan customization diperiksa pada 13 Oktober 2026. Fokus dan kuis pendamping diselaraskan dengan instruksi/kode langkah, bukan hanya ringkasan.','The “8 test” classroom was inspected in Chrome. Six project definitions (120 steps) and nine overview, progression, introduction, and customization PDFs were inspected on 13 October 2026. Focus and companion questions align with step instructions/code, beyond summary text.')+'</p><p>'+t('Platformer summary memuat beberapa istilah Dungeon; gunakan langkah Platformer 2–21 sebagai acuan. Rentang floor(random*5)+10 adalah 10–14. Beberapa slide customization lama memiliki typo CSS; gunakan kode aktif dan uji hasil.','The Platformer summary contains some Dungeon terms; use Platformer steps 2–21 as reference. floor(random*5)+10 ranges from 10–14. Some older customization slides contain CSS typos; use current code and test results.')+'</p><p>'+t('Assessment resmi Mobile Game Developer berisi 25 soal dan tetap di BSD. Soalnya tidak diperiksa satu per satu atau disalin. Web menyediakan 24 soal latihan asli; kunci dan pembahasan pendamping tidak diklaim sebagai kunci assessment resmi.','The official Mobile Game Developer assessment has 25 questions and remains in BSD. Its questions were not individually reviewed or copied. This website offers 24 original practice questions; their keys and explanations are not official assessment keys.')+'</p>'+BSD_SOURCES.map(s=>'<p class="source-link"><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a> · '+s.steps+' '+t('langkah','steps')+' · revision '+esc(s.revision)+'</p>').join('')+'<p class="source-link"><a href="https://app.bsd.education/resources/CORE%20CONTENT/TechNovators/Mobile%20Game%20Developer/General%20Resources/Mobile%20Game%20Developer%20-%20Overview.pdf" target="_blank" rel="noopener noreferrer">BSD Course Overview</a> · <a href="https://app.bsd.education/resources/CORE%20CONTENT/Standard%20Alignments/Course%20Progression/TechNovators%20Course%20Progression%20Documents/Mobile%20Game%20Developer%20-%20Course%20Progression.pdf" target="_blank" rel="noopener noreferrer">BSD Course Progression</a></p></details></div>';}
function guideText(){if(!teacherMode())return '';return '# Grade 8 · BSD Mobile Game Developer\n\n8 × 80 minutes. Condensed core plan; teacher Sandbox checkpoints required for meetings 3–6. Full course overview allocation: 25 hours.\n\n'+LESSONS.map(l=>'## '+l.id+'. '+tx(l.title)+'\n\n'+tx(l.goal)+'\n'+l.range+'\n\n'+l.tasks.map((s,i)=>(i+1)+'. '+tx(s)).join('\n')+'\n\nChallenge: '+tx(l.challenge)+'\nResult: '+tx(l.result)+'\nTest: '+tx(l.check)+'\nPreparation: '+tx(l.prep)+'\nSpoken question: '+tx(l.oral)+'\nBCW/WKA: '+tx(l.wka)+'\n\nPractice keys (original companion bank):\n'+l.questions.map(q=>tx(q.stem)+'\n'+tx(q.options[q.key])+' — '+tx(q.why)).join('\n\n')).join('\n\n');}
function projectHTML(){return '<p class="eyebrow">'+t('KARYA FINAL · PERTEMUAN 7–8','FINAL WORK · MEETINGS 7–8')+'</p><h1>'+t('Satu game. Versimu sendiri.','One game. Your own version.')+'</h1><div class="classroom"><section class="panel"><h2>'+t('Yang dikumpulkan','What to submit')+'</h2><ul class="project-list">'+[t('Tautan satu game pilihan yang bisa dimainkan.','A link to one playable game of your choice.'),t('Satu perubahan visual dan satu perubahan aturan.','One visual change and one rule change.'),t('Sumber aset, satu hasil uji teman, dan bukti revisi.','Asset sources, one peer-test finding, and revision evidence.'),t('Penjelasan satu alur input → kode → hasil serta modifikasi individual.','Explain one input → code → result flow and make an individual modification.')].map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul></section><section class="panel"><h2>'+t('Guru memeriksa','Your teacher checks')+'</h2><ul class="project-list">'+[t('Fungsi: kontrol, skor/HP/pola, dan kondisi akhir bekerja sesuai game.','Function: controls, score/HP/pattern, and end conditions work for the chosen game.'),t('Pemahaman: kamu menunjuk kode dan menjelaskan akibatnya.','Understanding: you point to code and explain its effect.'),t('Modifikasi: perubahanmu punya alasan dan tetap berfungsi.','Modification: your change has a reason and still works.'),t('Proses: uji, revisi, dan sumber aset dicatat secara jujur.','Process: tests, revisions, and asset sources are recorded honestly.')].map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul><p class="small">'+t('Nilai resmi dan bobot mengikuti penilaian guru di CS.Report. Skor latihan web tidak otomatis menjadi nilai.','Official grades and weights follow your teacher’s CS.Report assessment. Website practice scores do not automatically become grades.')+'</p><a class="btn" href="#lesson/7">'+t('Buka tugas modifikasi →','Open the modification task →')+'</a></section></div>';}
function route(){const [page,id]=location.hash.replace(/^#/,'').split('/');currentLesson=null;if(page==='teacher'&&!teacherMode()){location.hash='#home';return route();}let html;if(page==='lesson'){currentLesson=LESSONS.find(l=>l.id===Number(id));if(!currentLesson){location.hash='#home';return route();}html=lessonHTML(currentLesson);}else if(page==='teacher')html=teacherHTML();else if(page==='project')html=projectHTML();else html=homeHTML();$('main').innerHTML=html;if(currentLesson)bindLesson(currentLesson);if(page==='teacher')$('download-guide').addEventListener('click',()=>download('grade8-game-studio-guides-'+language+'.md',guideText()));document.title=(currentLesson?tx(currentLesson.title)+' · ':'')+'Game Studio · Grade 8';window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true});}
$('language').addEventListener('change',event=>{language=event.target.value;try{localStorage.setItem('cs-report-grade8-language',language);}catch{}const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);localizeShell();if(g8Session){$('learner-class').textContent=teacherMode()?t('Review guru · Kelas 8','Teacher review · Grade 8'):t('Kelas ','Class ')+g8Session.className;route();}});
async function start(){localizeShell();if(!(await initializeG8Access()))return;restorePractice();$('nav-teacher').hidden=!teacherMode();$('review-banner').hidden=!(teacherMode()||g8Session.isLocalPreview);$('review-banner').textContent=teacherMode()?t('Review guru. Catatan ini terpisah dari siswa.','Teacher review. These records are separate from students.'):t('Pratinjau lokal dengan siswa uji. Tanpa data siswa nyata.','Local preview with a test student. No real student data.');window.addEventListener('hashchange',route);route();}
start().catch(()=>{$('gate-copy').textContent=t('Materi belum termuat. Buka ulang dari CS.Report.','Materials could not load. Reopen from CS.Report.');});
